import re

# %% ../../../nbs/01_helper_22.latex.comments.ipynb #56b4a1f6
def remove_comments(text: str) -> str:
    # Find all occurrences of the comment pattern %[^\n]*
    return re.sub(r"%[^\n]*", "", text)
